        /// <summary>
        /// Emit warnings for custom members that will be silently bypassed in favor of the built-in
        /// element access and conversion mechanisms that the compiler provides for inline array types.
        /// </summary>
        private void CheckInlineArrayMembersNotUsed(FieldSymbol elementField, BindingDiagnosticBag diagnostics)
        {
            TypeWithAnnotations elementType = elementField.TypeWithAnnotations;
            NamedTypeSymbol spanType = DeclaringCompilation.GetWellKnownType(WellKnownType.System_Span_T);
            NamedTypeSymbol readOnlySpanType = DeclaringCompilation.GetWellKnownType(WellKnownType.System_ReadOnlySpan_T);
            NamedTypeSymbol indexType = DeclaringCompilation.GetWellKnownType(WellKnownType.System_Index);
            NamedTypeSymbol rangeType = DeclaringCompilation.GetWellKnownType(WellKnownType.System_Range);

            foreach (var member in GetMembers())
            {
                switch (member)
                {
                    case PropertySymbol { IsIndexer: true } indexer:
                        // An 'int', 'System.Index', or 'System.Range' indexer is bypassed in favor of the built-in
                        // element access for inline arrays. Ref structs don't have the built-in element access.
                        if (!IsRefLikeType &&
                            !indexer.IsExplicitInterfaceImplementation &&
                            indexer.ParameterCount == 1 &&
                            indexer.Parameters[0].Type is { } indexerParameterType &&
                            (indexerParameterType.SpecialType == SpecialType.System_Int32 ||
                             indexerParameterType.Equals(indexType, TypeCompareKind.AllIgnoreOptions) ||
                             indexerParameterType.Equals(rangeType, TypeCompareKind.AllIgnoreOptions)))
                        {
                            diagnostics.Add(ErrorCode.WRN_InlineArrayIndexerNotUsed, indexer.GetFirstLocation());
                        }
                        break;

                    case MethodSymbol method:
                        switch (method.MethodKind)
                        {
                            case MethodKind.Ordinary:
                                // A 'Slice(int, int)' method is bypassed in favor of the built-in range based
                                // element access for inline arrays.
                                if (method.Name == WellKnownMemberNames.SliceMethodName &&
                                    !method.IsExplicitInterfaceImplementation &&
                                    !method.ReturnsVoid &&
                                    method.ParameterCount == 2 &&
                                    method.Parameters[0].Type.SpecialType == SpecialType.System_Int32 &&
                                    method.Parameters[1].Type.SpecialType == SpecialType.System_Int32)
                                {
                                    diagnostics.Add(ErrorCode.WRN_InlineArraySliceNotUsed, method.GetFirstLocation());
                                }
                                break;

                            case MethodKind.Conversion:
                                // A conversion operator to 'Span<T>'/'ReadOnlySpan<T>' (where 'T' is the element type)
                                // is bypassed in favor of the built-in conversion for inline arrays. The built-in
                                // conversion is not applicable to a nullable variant of the declaring type.
                                if (method.ReturnType is NamedTypeSymbol { } returnType &&
                                    (returnType.OriginalDefinition.Equals(spanType, TypeCompareKind.AllIgnoreOptions) ||
                                     returnType.OriginalDefinition.Equals(readOnlySpanType, TypeCompareKind.AllIgnoreOptions)) &&
                                    returnType.TypeArgumentsWithAnnotationsNoUseSiteDiagnostics is [var spanElementType] &&
                                    spanElementType.Equals(elementType, TypeCompareKind.AllIgnoreOptions) &&
                                    method.ParameterCount == 1 &&
                                    method.Parameters[0].Type.Equals(this, TypeCompareKind.AllIgnoreOptions))
                                {
                                    diagnostics.Add(ErrorCode.WRN_InlineArrayConversionOperatorNotUsed, method.GetFirstLocation());
                                }
                                break;
                        }
                        break;
                }
            }
